                           re.IGNORECASE)


def _valid_date(dt: datetime) -> bool:
    return 2000 <= dt.year <= 2099 and 1 <= dt.month <= 12 and 1 <= dt.day <= 31


def _try_parse(tok: str, fmt: str) -> str | None:
    try:
        dt = datetime.strptime(tok, fmt)
        if _valid_date(dt):
